"use client"

import * as React from "react"
import { Trash2 } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"
import {
  formatMoney,
  lineCents,
  resolveCheckoutLabels,
  type CheckoutLabels,
  type CheckoutLine,
  type CheckoutTotals,
} from "@/lib/checkout"
import { NumberField } from "@/components/ui/number-field"

export type OrderSummaryStatus = "ready" | "empty" | "loading" | "error"

export type OrderSummaryProps = {
  lines: readonly CheckoutLine[]
  totals: CheckoutTotals
  currency?: string
  locale?: string
  status?: OrderSummaryStatus
  onQtyChange?: (id: string, qty: number) => void
  onRemove?: (id: string) => void
  onBackToStore?: () => void
  onRetry?: () => void
  storeHref?: string
  labels?: Partial<CheckoutLabels>
  className?: string
}

function Money({ cents, locale, currency }: { cents: number; locale: string; currency: string }) {
  return <span className="text-end tabular-nums">{formatMoney(cents, locale, currency)}</span>
}

function TotalRow({ label, value, strong = false }: { label: string; value: React.ReactNode; strong?: boolean }) {
  return (
    <div className={cn("flex min-w-0 items-baseline justify-between gap-3", strong && "text-base font-medium")}>
      <dt className={strong ? undefined : "text-muted-foreground"}>{label}</dt>
      <dd className="min-w-0 text-end">{value}</dd>
    </div>
  )
}

export function OrderSummary({
  lines,
  totals,
  currency = "MXN",
  locale = "es-MX",
  status = "ready",
  onQtyChange,
  onRemove,
  onBackToStore,
  onRetry,
  storeHref,
  labels,
  className,
}: OrderSummaryProps) {
  const copy = resolveCheckoutLabels(locale, labels)
  const titleId = React.useId()
  const empty = status === "empty" || (status === "ready" && lines.length === 0)
  const view = empty ? "empty" : status

  return (
    <section
      data-slot="order-summary"
      data-status={view}
      aria-labelledby={titleId}
      aria-busy={view === "loading" ? true : undefined}
      className={cn("min-w-0 rounded-xl border border-border bg-card p-4 text-card-foreground", className)}
    >
      <h2 id={titleId} className="text-base font-medium">
        {copy.summaryTitle}
      </h2>

      {view === "loading" ? (
        <div className="mt-4 grid gap-3">
          <p className="sr-only">{copy.loading}</p>
          <Skeleton className="h-11 w-full motion-reduce:animate-none" />
          <Skeleton className="h-11 w-full motion-reduce:animate-none" />
          <Skeleton className="ms-auto h-4 w-28 motion-reduce:animate-none" />
        </div>
      ) : null}

      {view === "error" ? (
        <div role="alert" className="mt-4 grid gap-3 rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive">
          <p>{copy.errorTitle}</p>
          <Button type="button" variant="outline" className="min-h-11 justify-self-start bg-background" onClick={onRetry}>
            {copy.retry}
          </Button>
        </div>
      ) : null}

      {view === "empty" ? (
        <div className="mt-4 grid gap-3">
          <p className="font-medium">{copy.emptyTitle}</p>
          <p className="text-sm text-muted-foreground">{copy.emptyBody}</p>
          {storeHref ? (
            <Button asChild className="min-h-11 w-full">
              <a href={storeHref}>{copy.backToStore}</a>
            </Button>
          ) : (
            <Button type="button" className="min-h-11 w-full" onClick={onBackToStore}>
              {copy.backToStore}
            </Button>
          )}
        </div>
      ) : null}

      {view === "ready" ? (
        <>
          <ul className="mt-4 grid gap-3">
            {lines.map((line) => (
              <li key={line.id} className="flex min-w-0 flex-wrap items-start gap-3 border-b border-border pb-3">
                {line.imageUrl ? (
                  // The host supplies the URL. This file cannot depend on next/image.
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={line.imageUrl} alt="" className="size-11 shrink-0 rounded-md object-cover" />
                ) : (
                  <span className="grid size-11 shrink-0 place-items-center rounded-md bg-muted text-xs font-medium text-muted-foreground" aria-hidden="true">
                    {line.title.slice(0, 1)}
                  </span>
                )}
                <div className="min-w-0 flex-1 basis-40">
                  <p className="break-words font-medium">{line.title}</p>
                  {line.variant ? <p className="break-words text-xs text-muted-foreground">{line.variant}</p> : null}
                  <p className="mt-1 text-sm">
                    <Money cents={lineCents(line)} locale={locale} currency={currency} />
                  </p>
                </div>
                <NumberField
                  label={`${copy.quantity}, ${line.title}`}
                  size="sm"
                  min={1}
                  max={99}
                  value={line.qty}
                  locale={locale}
                  onValueChange={(qty) => onQtyChange?.(line.id, qty)}
                  disabled={!onQtyChange}
                  classNames={{ step: "size-11", root: "max-w-none" }}
                />
                <Button
                  type="button"
                  variant="outline"
                  className="size-11"
                  aria-label={`${copy.remove} ${line.title}`}
                  disabled={!onRemove}
                  onClick={() => onRemove?.(line.id)}
                >
                  <Trash2 aria-hidden="true" />
                </Button>
              </li>
            ))}
          </ul>
          <dl className="mt-4 grid gap-2 text-sm">
            <TotalRow label={copy.subtotal} value={<Money cents={totals.subtotal} locale={locale} currency={currency} />} />
            <TotalRow label={copy.shipping} value={<Money cents={totals.shipping} locale={locale} currency={currency} />} />
            {totals.discount > 0 ? (
              <TotalRow label={copy.discount} value={<Money cents={-totals.discount} locale={locale} currency={currency} />} />
            ) : null}
            {totals.tax != null ? <TotalRow label={copy.tax} value={<Money cents={totals.tax} locale={locale} currency={currency} />} /> : null}
            <TotalRow
              strong
              label={copy.total}
              value={
                <span className="text-end font-medium tabular-nums" aria-live="polite">
                  {formatMoney(totals.total, locale, currency)}
                </span>
              }
            />
          </dl>
        </>
      ) : null}
    </section>
  )
}

"use client"

import * as React from "react"
import { Banknote, CreditCard, Landmark, Store, Truck, Zap, type LucideIcon } from "lucide-react"

import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { cn } from "@/lib/utils"
import {
  checkoutFieldErrors,
  formatMoney,
  resolveCheckoutLabels,
  type CheckoutDraft,
  type CheckoutField,
  type CheckoutIcon,
  type CheckoutLabels,
  type CheckoutLayout,
  type CheckoutMethod,
} from "@/lib/checkout"
import { ActionButton } from "@/components/ui/action-button"
import { ActionFooter } from "@/components/ui/action-footer"
import { PhoneInput } from "@/components/ui/phone-input"
import { RadioCards } from "@/components/ui/radio-cards"
import { Stepper } from "@/components/ui/stepper"

const ICONS: Record<CheckoutIcon, LucideIcon> = {
  truck: Truck,
  fast: Zap,
  store: Store,
  card: CreditCard,
  bank: Landmark,
  cash: Banknote,
}

export type CheckoutFormProps = {
  layout: CheckoutLayout
  draft: CheckoutDraft
  onDraftChange: (patch: Partial<CheckoutDraft>) => void
  shippingMethods: readonly CheckoutMethod[]
  paymentMethods: readonly CheckoutMethod[]
  currency?: string
  locale?: string
  labels?: Partial<CheckoutLabels>
  couponError?: string | null
  appliedCoupon?: string | null
  onApplyCoupon?: (code: string) => void | Promise<void>
  onSubmit: (draft: CheckoutDraft) => Promise<void>
  onBackToStore?: () => void
  showStepper?: boolean
  disabled?: boolean
  busy?: boolean
  className?: string
}

function MethodIcon({ name }: { name: CheckoutIcon }) {
  const Icon = ICONS[name]
  return <Icon aria-hidden="true" />
}

function moneyOrFree(cents: number | undefined, locale: string, currency: string, free: string) {
  if (!cents) return free
  return formatMoney(cents, locale, currency)
}

export function CheckoutForm({
  layout,
  draft,
  onDraftChange,
  shippingMethods,
  paymentMethods,
  currency = "MXN",
  locale = "es-MX",
  labels,
  couponError,
  appliedCoupon,
  onApplyCoupon,
  onSubmit,
  onBackToStore,
  showStepper,
  disabled = false,
  busy = false,
  className,
}: CheckoutFormProps) {
  const copy = resolveCheckoutLabels(locale, labels)
  const baseId = React.useId()
  const alertId = `${baseId}-errors`
  const couponId = `${baseId}-coupon`
  const [errors, setErrors] = React.useState<Partial<Record<CheckoutField, string>>>({})
  const [open, setOpen] = React.useState<string[]>(["contact", "shipping", "payment", "coupon"])
  const focusErrors = React.useRef(false)
  const progress = layout !== "single" && (showStepper ?? true)
  const country = locale.toLowerCase().startsWith("es") ? "MX" : "US"
  const locked = disabled || busy

  const sections = React.useMemo(
    () => [
      { id: "contact", label: copy.stepContact },
      { id: "shipping", label: copy.stepShipping },
      { id: "payment", label: copy.stepPayment },
    ],
    [copy.stepContact, copy.stepPayment, copy.stepShipping],
  )

  const step = !draft.email.trim() ? 0 : !draft.shippingMethodId ? 1 : 2

  React.useEffect(() => {
    if (!focusErrors.current) return
    focusErrors.current = false
    document.getElementById(alertId)?.focus()
  }, [errors, alertId])

  async function submit() {
    const next = checkoutFieldErrors(draft, copy)
    setErrors(next)
    if (Object.keys(next).length) {
      focusErrors.current = true
      throw new Error("invalid")
    }
    await onSubmit(draft)
  }

  function patch(next: Partial<CheckoutDraft>) {
    onDraftChange(next)
  }

  function openSection(id: string) {
    setOpen((current) => (current.includes(id) ? current : [...current, id]))
    document.getElementById(`${baseId}-section-${id}`)?.focus()
  }

  const contact = (
    <div className="grid gap-3">
      <TextField
        id={`${baseId}-email`}
        label={copy.email}
        type="email"
        autoComplete="email"
        value={draft.email}
        error={errors.email}
        disabled={locked}
        onChange={(email) => patch({ email })}
      />
      <PhoneInput
        id={`${baseId}-phone`}
        label={copy.phone}
        value={draft.phone}
        defaultCountry={country}
        preferredCountries={["MX", "US"]}
        error={errors.phone}
        disabled={locked}
        required
        onValueChange={(phone) => patch({ phone })}
      />
    </div>
  )

  const address = (
    <fieldset className="grid gap-3" disabled={locked}>
      <legend className="sr-only">{copy.shippingTitle}</legend>
      <TextField id={`${baseId}-name`} label={copy.fullName} autoComplete="name" value={draft.name} error={errors.name} disabled={locked} onChange={(name) => patch({ name })} />
      <TextField id={`${baseId}-line1`} label={copy.line1} autoComplete="address-line1" value={draft.line1} error={errors.line1} disabled={locked} onChange={(line1) => patch({ line1 })} />
      <TextField id={`${baseId}-line2`} label={copy.line2} autoComplete="address-line2" value={draft.line2} disabled={locked} onChange={(line2) => patch({ line2 })} />
      <div className="grid gap-3 sm:grid-cols-2">
        <TextField id={`${baseId}-city`} label={copy.city} autoComplete="address-level2" value={draft.city} error={errors.city} disabled={locked} onChange={(city) => patch({ city })} />
        <TextField id={`${baseId}-region`} label={copy.region} autoComplete="address-level1" value={draft.region} error={errors.region} disabled={locked} onChange={(region) => patch({ region })} />
      </div>
      <div className="grid gap-3 sm:grid-cols-2">
        <TextField id={`${baseId}-postal`} label={copy.postalCode} autoComplete="postal-code" value={draft.postalCode} error={errors.postalCode} disabled={locked} onChange={(postalCode) => patch({ postalCode })} />
        <TextField id={`${baseId}-country`} label={copy.country} autoComplete="country-name" value={draft.country} error={errors.country} disabled={locked} onChange={(countryName) => patch({ country: countryName })} />
      </div>
    </fieldset>
  )

  const shipping = (
    <div className="grid gap-3">
      {address}
      <RadioCards
        aria-label={copy.shippingTitle}
        layout="list"
        value={draft.shippingMethodId || null}
        disabled={locked}
        onValueChange={(shippingMethodId) => patch({ shippingMethodId })}
        options={shippingMethods.map((method) => ({
          value: method.id,
          label: method.label,
          description: method.description,
          meta: moneyOrFree(method.priceCents, locale, currency, copy.free),
          icon: <MethodIcon name={method.icon ?? "truck"} />,
        }))}
        classNames={{ card: "min-h-11" }}
      />
      {errors.shippingMethodId ? <p className="text-xs text-destructive">{errors.shippingMethodId}</p> : null}
    </div>
  )

  const payment = (
    <div className="grid gap-3">
      <RadioCards
        aria-label={copy.paymentTitle}
        layout="list"
        value={draft.paymentMethodId || null}
        disabled={locked}
        onValueChange={(paymentMethodId) => patch({ paymentMethodId })}
        options={paymentMethods.map((method) => ({
          value: method.id,
          label: method.label,
          description: method.description,
          icon: <MethodIcon name={method.icon ?? "card"} />,
        }))}
        classNames={{ card: "min-h-11" }}
      />
      {errors.paymentMethodId ? <p className="text-xs text-destructive">{errors.paymentMethodId}</p> : null}
    </div>
  )

  const coupon = (
    <div className="grid gap-2">
      <Label htmlFor={couponId}>{copy.coupon}</Label>
      <div className="flex min-w-0 flex-wrap items-center gap-2">
        <Input
          id={couponId}
          value={draft.couponCode}
          disabled={locked}
          autoComplete="off"
          aria-invalid={couponError ? true : undefined}
          aria-describedby={couponError ? `${couponId}-error` : appliedCoupon ? `${couponId}-applied` : undefined}
          onChange={(event) => patch({ couponCode: event.target.value })}
          onKeyDown={(event) => {
            if (event.key !== "Enter") return
            event.preventDefault()
            event.stopPropagation()
            void onApplyCoupon?.(draft.couponCode)
          }}
          className="h-11 min-h-11 min-w-0 flex-1"
        />
        <button
          type="button"
          className="inline-flex min-h-11 items-center justify-center rounded-lg border border-border bg-background px-4 text-sm font-medium text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:opacity-50"
          disabled={locked}
          onClick={() => void onApplyCoupon?.(draft.couponCode)}
        >
          {copy.applyCoupon}
        </button>
      </div>
      {couponError ? (
        <p id={`${couponId}-error`} role="alert" className="text-xs text-destructive">
          {couponError}
        </p>
      ) : null}
      {appliedCoupon && !couponError ? (
        <p id={`${couponId}-applied`} role="status" className="text-xs text-muted-foreground">
          {copy.couponApplied}: {appliedCoupon}
        </p>
      ) : null}
    </div>
  )

  const blocks = [
    { id: "contact", title: copy.contactTitle, body: contact },
    { id: "shipping", title: copy.shippingTitle, body: shipping },
    { id: "payment", title: copy.paymentTitle, body: payment },
    { id: "coupon", title: copy.couponTitle, body: coupon },
  ]

  return (
    <form
      data-slot="checkout-form"
      data-layout={layout}
      aria-busy={busy ? true : undefined}
      className={cn("grid min-w-0 gap-4", className)}
      onSubmit={(event) => {
        event.preventDefault()
        void submit().catch(() => undefined)
      }}
    >
      {progress ? (
        <Stepper
          steps={sections}
          current={step}
          label={copy.stepsLabel}
          completeLabel={copy.stepsComplete}
          onStepSelect={(index) => {
            const id = sections[index]?.id
            if (id) openSection(id)
          }}
        />
      ) : null}

      {Object.keys(errors).length ? (
        <div id={alertId} role="alert" tabIndex={-1} className="rounded-lg border border-destructive/40 bg-destructive/10 p-3 text-sm text-destructive outline-none">
          <ul className="grid gap-1">
            {Object.entries(errors).map(([field, message]) => (
              <li key={field}>{message}</li>
            ))}
          </ul>
        </div>
      ) : null}

      {layout === "accordion" ? (
        <Accordion type="multiple" value={open} onValueChange={setOpen}>
          {blocks.map((block) => (
            <AccordionItem key={block.id} value={block.id}>
              <AccordionTrigger id={`${baseId}-section-${block.id}`}>{block.title}</AccordionTrigger>
              <AccordionContent>{block.body}</AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
      ) : (
        blocks.map((block) => (
          <section key={block.id} aria-labelledby={`${baseId}-section-${block.id}`} className="grid min-w-0 gap-3">
            <h2 id={`${baseId}-section-${block.id}`} tabIndex={-1} className="text-base font-medium outline-none">
              {block.title}
            </h2>
            {block.body}
          </section>
        ))
      )}

      <ActionFooter
        hint={copy.orderHint}
        secondary={onBackToStore ? { label: copy.backToStore, onSelect: onBackToStore } : undefined}
        disabled={locked}
      />
      <ActionButton
        label={copy.placeOrder}
        pendingLabel={copy.placingOrder}
        successLabel={copy.orderPlaced}
        disabled={locked}
        className="min-h-11 w-full"
        onAction={submit}
      />
    </form>
  )
}

function TextField({
  id,
  label,
  value,
  onChange,
  error,
  disabled,
  type = "text",
  autoComplete,
}: {
  id: string
  label: string
  value: string
  onChange: (value: string) => void
  error?: string
  disabled?: boolean
  type?: string
  autoComplete?: string
}) {
  const errorId = error ? `${id}-error` : undefined
  return (
    <div className="grid min-w-0 gap-1.5">
      <Label htmlFor={id}>{label}</Label>
      <Input
        id={id}
        type={type}
        value={value}
        disabled={disabled}
        autoComplete={autoComplete}
        aria-invalid={error ? true : undefined}
        aria-describedby={errorId}
        onChange={(event) => onChange(event.target.value)}
        className="h-11 min-h-11 min-w-0"
      />
      {error ? (
        <p id={errorId} className="text-xs text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}

"use client"

import * as React from "react"
import { Check } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  applyCoupon,
  findCoupon,
  formatMoney,
  methodPrice,
  recalcTotals,
  resolveCheckoutLabels,
  type CheckoutDraft,
  type CheckoutLabels,
  type CheckoutLayout,
  type CheckoutLine,
  type CheckoutMethod,
  type CheckoutOrder,
  type CheckoutStatus,
  type CouponOffer,
} from "@/lib/checkout"
import { useMinWidth } from "@/hooks/use-min-width"
import { BottomSheet } from "@/components/ui/bottom-sheet"
import { CheckoutForm } from "@/components/ui/checkout-form"
import { OrderSummary } from "@/components/ui/order-summary"

const WIDE = 1024

export type CheckoutPresetCoupon = {
  code: string
  error?: "invalid" | "already-applied"
}

export type CheckoutPageProps = {
  lines?: readonly CheckoutLine[]
  layout?: CheckoutLayout
  currency?: string
  locale?: string
  status?: CheckoutStatus
  shippingMethods?: readonly CheckoutMethod[]
  paymentMethods?: readonly CheckoutMethod[]
  coupons?: readonly CouponOffer[]
  defaultValues?: Partial<CheckoutDraft>
  presetCoupon?: CheckoutPresetCoupon
  taxCents?: number
  labels?: Partial<CheckoutLabels>
  showStepper?: boolean
  onQtyChange?: (id: string, qty: number) => void
  onRemove?: (id: string) => void
  onApplyCoupon?: (code: string) => void | Promise<void>
  onPlaceOrder?: (order: CheckoutOrder) => void | Promise<void>
  onRetry?: () => void
  onBackToStore?: () => void
  storeHref?: string
  className?: string
}

function blankDraft(partial?: Partial<CheckoutDraft>, couponCode = ""): CheckoutDraft {
  return {
    email: "",
    phone: "",
    name: "",
    line1: "",
    line2: "",
    city: "",
    region: "",
    postalCode: "",
    country: "",
    shippingMethodId: "",
    paymentMethodId: "",
    ...partial,
    couponCode: partial?.couponCode ?? couponCode,
  }
}

export function CheckoutPage({
  lines = [],
  layout = "single",
  currency = "MXN",
  locale = "es-MX",
  status,
  shippingMethods = [],
  paymentMethods = [],
  coupons = [],
  defaultValues,
  presetCoupon,
  taxCents,
  labels,
  showStepper,
  onQtyChange,
  onRemove,
  onApplyCoupon,
  onPlaceOrder,
  onRetry,
  onBackToStore,
  storeHref,
  className,
}: CheckoutPageProps) {
  const copy = resolveCheckoutLabels(locale, labels)
  const wide = useMinWidth(WIDE)
  const [qty, setQty] = React.useState<Record<string, number>>({})
  const [removed, setRemoved] = React.useState<string[]>([])
  const [draft, setDraft] = React.useState(() => blankDraft(defaultValues, presetCoupon?.code ?? ""))
  const [applied, setApplied] = React.useState<CouponOffer | null>(() =>
    presetCoupon && !presetCoupon.error ? findCoupon(coupons, presetCoupon.code) : null,
  )
  const [couponKind, setCouponKind] = React.useState<"invalid" | "already-applied" | null>(presetCoupon?.error ?? null)
  const [placed, setPlaced] = React.useState(false)

  const viewLines = lines
    .filter((line) => !removed.includes(line.id))
    .map((line) => ({ ...line, qty: qty[line.id] ?? line.qty }))
  const shipping = methodPrice(shippingMethods, draft.shippingMethodId)
  const totals = applied
    ? applyCoupon(viewLines, shipping, applied, { taxCents }).totals
    : recalcTotals(viewLines, shipping, 0, taxCents)

  const viewStatus: CheckoutStatus = placed
    ? "success"
    : status === "loading" || status === "error" || status === "submitting" || status === "success"
      ? status
      : viewLines.length === 0
        ? "empty"
        : "ready"

  const couponError =
    couponKind === "invalid" ? copy.couponInvalid : couponKind === "already-applied" ? copy.couponAlready : null
  const stack = layout === "two-column" && !wide
  const interactive = viewStatus === "ready" || viewStatus === "submitting"

  function changeQty(id: string, next: number) {
    setQty((current) => ({ ...current, [id]: next }))
    onQtyChange?.(id, next)
  }

  function removeLine(id: string) {
    setRemoved((current) => [...current, id])
    onRemove?.(id)
  }

  async function apply(code: string) {
    const offer = findCoupon(coupons, code)
    const result = applyCoupon(viewLines, shipping, offer, {
      appliedCode: applied?.code ?? null,
      discountCents: applied ? totals.discount : 0,
      taxCents,
    })
    if (result.error) {
      setCouponKind(result.error)
      return
    }
    setApplied(offer)
    setCouponKind(null)
    setDraft((current) => ({ ...current, couponCode: offer?.code ?? code }))
    await onApplyCoupon?.(code)
  }

  async function place(next: CheckoutDraft) {
    await onPlaceOrder?.({
      lines: viewLines,
      draft: next,
      couponCode: applied?.code ?? null,
      totals,
    })
    setPlaced(true)
  }

  const summary = (
    <OrderSummary
      lines={viewLines}
      totals={totals}
      currency={currency}
      locale={locale}
      labels={copy}
      status={viewStatus === "empty" || viewStatus === "loading" || viewStatus === "error" ? viewStatus : "ready"}
      onQtyChange={interactive ? changeQty : undefined}
      onRemove={interactive ? removeLine : undefined}
      onBackToStore={onBackToStore}
      onRetry={onRetry}
      storeHref={storeHref}
    />
  )

  const form = (
    <CheckoutForm
      layout={layout}
      draft={draft}
      onDraftChange={(patch) => setDraft((current) => ({ ...current, ...patch }))}
      shippingMethods={shippingMethods}
      paymentMethods={paymentMethods}
      currency={currency}
      locale={locale}
      labels={copy}
      couponError={couponError}
      appliedCoupon={applied?.code ?? null}
      onApplyCoupon={apply}
      onSubmit={place}
      onBackToStore={onBackToStore}
      showStepper={showStepper}
      busy={viewStatus === "submitting"}
    />
  )

  return (
    <section
      data-slot="checkout-page"
      data-layout={layout}
      data-status={viewStatus}
      data-stacked={stack ? "true" : "false"}
      aria-label={copy.formLabel}
      aria-busy={viewStatus === "loading" || viewStatus === "submitting" ? true : undefined}
      className={cn("grid min-w-0 max-w-full gap-4", className)}
    >
      {viewStatus === "success" ? (
        <div role="status" className="grid min-w-0 justify-items-start gap-2 rounded-xl border border-border bg-card p-6 text-card-foreground">
          <Check className="size-5 text-primary" aria-hidden="true" />
          <h2 className="text-lg font-medium">{copy.successTitle}</h2>
          <p className="max-w-prose text-sm text-muted-foreground">{copy.successBody}</p>
          <p className="text-end text-base font-medium tabular-nums">{formatMoney(totals.total, locale, currency)}</p>
        </div>
      ) : null}

      {!interactive && viewStatus !== "success" ? summary : null}

      {interactive && stack ? (
        <>
          <div className="flex min-w-0 items-center justify-between gap-3 rounded-xl border border-border bg-card p-3">
            <div className="min-w-0">
              <p className="text-sm text-muted-foreground">{copy.summaryTitle}</p>
              <p className="font-medium tabular-nums">{formatMoney(totals.total, locale, currency)}</p>
            </div>
            <BottomSheet
              title={copy.summaryTitle}
              closeLabel={copy.closeSummary}
              trigger={
                <button
                  type="button"
                  className="inline-flex min-h-11 shrink-0 items-center rounded-lg bg-primary px-3 text-sm font-medium text-primary-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                >
                  {copy.viewSummary}
                </button>
              }
            >
              {summary}
            </BottomSheet>
          </div>
          {form}
        </>
      ) : null}

      {interactive && !stack && layout === "two-column" ? (
        <div className="grid min-w-0 items-start gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(16rem,22rem)]">
          {form}
          {summary}
        </div>
      ) : null}

      {interactive && !stack && layout !== "two-column" ? (
        <div className="grid min-w-0 gap-6">
          {summary}
          {form}
        </div>
      ) : null}
    </section>
  )
}
